// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.engineimport android.app.NotificationChannelimport android.app.NotificationManagerimport android.content.Contextimport android.media.AudioAttributesimport android.media.RingtoneManagerimport android.os.Buildimport android.speech.tts.TextToSpeechimport androidx.core.app.NotificationCompatimport com.roshan.persona.automation.model.AutomationActionimport com.roshan.persona.automation.model.AutomationRuleimport com.roshan.persona.automation.model.AutomationTriggerimport com.roshan.persona.automation.model.LogicalOperatorimport com.roshan.persona.automation.scheduler.AutomationSchedulerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.skill.executor.SystemOperationExecutorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport java.util.Localeimport java.util.UUIDimport java.util.concurrent.ConcurrentHashMapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Automation Engine (Module 8). * * The engine is the source of truth for user-defined automation rules. It: * *   1. **Stores** rules in-memory (`ConcurrentHashMap<ruleId, AutomationRule>`). *      Room persistence is a v2 TODO — tracked separately. *   2. **Schedules** triggers via [Automatio // MEDIUM_FIX: Track in project backlognScheduler] when rules are created *      or updated. Disabling a rule cancels its scheduled work. *   3. **Fires** rules when a trigger fires. The actual firing is performed *      by [com.roshan.persona.automation.worker.AutomationWorker], which *      calls back into [fireRule] with the rule ID. *   4. **Executes** actions via [executeAction], delegating to the right *      primitive: *       - [AutomationAction.SystemAction]  → [SystemOperationExecutor] *       - [AutomationAction.SkillAction]   → BrainBus event emission *       - [AutomationAction.SpeakAction]   → Android `TextToSpeech` *       - [AutomationAction.NotifyAction]  → Android `NotificationManager` *       - [AutomationAction.ChainAction]   → recursive sequential execution * * The engine is `@Singleton`-scoped — there's exactly one instance per app * process. It's safe to call from any thread (all public methods are * thread-safe via ConcurrentHashMap + volatile TTS). * * Strategy reference: §2.2 — Automation is one of four Brain input modalities * (Voice/Text/Gesture/Automation). This engine is the production-side * counterpart: rules fire on triggers, not on user voice/text input. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2</a> */@Singletonclass AutomationEngine @Inject constructor(    @dagger.hilt.android.qualifiers.ApplicationContext private val context: Context,    private val scheduler: AutomationScheduler,    private val systemExecutor: SystemOperationExecutor,    private val brainBus: BrainBus,) {    companion object {        private const val TAG = "NOUS.Auto.Engine"        /** Notification channel ID for automation-fired notifications. */        const val NOTIFICATION_CHANNEL_ID = "nous_automation_channel"        /** Notification channel name (shown in Settings). */        const val NOTIFICATION_CHANNEL_NAME = "NOUS Automation"        /** Base notification ID for automation-fired notifications. */        const val NOTIFICATION_ID_BASE = 30000    }    /**     * In-memory rule store. Keyed by [AutomationRule.id].     *     * ConcurrentHashMap gives us:     *   - Thread-safe CRUD from any thread.     *   - Weakly-consistent iteration (acceptable for our use case — we     *     re-snapshot on every list call).     *     * TODO(v2): replace with Room `automation_rules` table for persistence.     */    private val rules = ConcurrentHashMap<String, AutomationRule>()    /**     * TTS engine for [AutomationAction.SpeakAction]. Initialized lazily on     * first use. `@Volatile` because TTS init is async — readers must see     * the latest reference.     */    @Volatile    private var tts: TextToSpeech? = null    /**     * Recent-fire history for compound triggers. Keyed by [AutomationRule.id],     * value = list of recent fire timestamps (epoch millis).     *     * Used by [evaluateCompoundTrigger] to decide whether all child triggers     * have fired within the AND-window.     */    private val compoundFireHistory = ConcurrentHashMap<String, MutableList<Long>>()    // ═══════════════════════════════════════════════════════════════════════════    // CRUD operations    // ═══════════════════════════════════════════════════════════════════════════    /**     * Create a new automation rule + schedule its trigger.     *     * @param name     user-facing rule name (e.g., "Morning Briefing").     * @param trigger  what fires the rule.     * @param action   what to do when triggered.     * @return the new rule's UUID.     */    fun createRule(        name: String,        trigger: AutomationTrigger,        action: AutomationAction,    ): String {        require(name.isNotBlank()) { "Rule name cannot be blank" }        val rule = AutomationRule(            id = UUID.randomUUID().toString(),            name = name.trim(),            trigger = trigger,            action = action,            isEnabled = true,        )        rules[rule.id] = rule        Timber.tag(TAG).i("Created rule '%s' (id=%s, trigger=%s)", rule.name, rule.id, rule.trigger::class.simpleName)        scheduler.schedule(rule)        return rule.id    }    /**     * Update an existing rule + reschedule its trigger.     *     * @return `true` if the rule was found + updated; `false` if not found.     */    fun updateRule(updated: AutomationRule): Boolean {        val existing = rules[updated.id] ?: run {            Timber.tag(TAG).w("updateRule: rule %s not found", updated.id)            return false        }        val merged = updated.copy(            createdAt = existing.createdAt,  // preserve original createdAt            updatedAt = System.currentTimeMillis(),        )        rules[updated.id] = merged        Timber.tag(TAG).i("Updated rule '%s' (id=%s)", merged.name, merged.id)        // Reschedule: cancel any existing work + schedule fresh.        scheduler.cancel(updated.id)        if (merged.isEnabled) {            scheduler.schedule(merged)        }        return true    }    /**     * Delete a rule + cancel its scheduled trigger.     *     * @return `true` if the rule was found + deleted; `false` if not found.     */    fun deleteRule(id: String): Boolean {        val removed = rules.remove(id)        if (removed == null) {            Timber.tag(TAG).w("deleteRule: rule %s not found", id)            return false        }        scheduler.cancel(id)        compoundFireHistory.remove(id)        Timber.tag(TAG).i("Deleted rule '%s' (id=%s)", removed.name, id)        return true    }    /**     * Enable a previously-disabled rule + schedule its trigger.     *     * @return `true` if the rule was found + enabled; `false` if not found.     */    fun enableRule(id: String): Boolean {        val existing = rules[id] ?: return false        if (existing.isEnabled) return true  // already enabled — no-op        val enabled = existing.copy(isEnabled = true, updatedAt = System.currentTimeMillis())        rules[id] = enabled        scheduler.schedule(enabled)        Timber.tag(TAG).i("Enabled rule '%s' (id=%s)", enabled.name, id)        return true    }    /**     * Disable a rule + cancel its scheduled trigger. Rule is NOT deleted —     * user can re-enable later via [enableRule].     *     * @return `true` if the rule was found + disabled; `false` if not found.     */    fun disableRule(id: String): Boolean {        val existing = rules[id] ?: return false        if (!existing.isEnabled) return true  // already disabled — no-op        val disabled = existing.copy(isEnabled = false, updatedAt = System.currentTimeMillis())        rules[id] = disabled        scheduler.cancel(id)        Timber.tag(TAG).i("Disabled rule '%s' (id=%s)", disabled.name, id)        return true    }    /**     * List all rules (enabled + disabled), snapshot copy.     *     * Returns a stable list — iteration over the returned list is safe even     * if the underlying store changes concurrently.     */    fun listRules(): List<AutomationRule> = rules.values.toList().sortedBy { it.createdAt }    /**     * Get a rule by ID.     */    fun getRule(id: String): AutomationRule? = rules[id]    // ═══════════════════════════════════════════════════════════════════════════    // Firing + execution    // ═══════════════════════════════════════════════════════════════════════════    /**     * Fire a rule — called by [com.roshan.persona.automation.worker.AutomationWorker]     * when the trigger fires.     *     * Steps:     *   1. Look up the rule. If not found / disabled → return [FireResult.Skipped].     *   2. For [AutomationTrigger.CompoundTrigger] — record this fire in     *      history + check whether the operator condition is satisfied.     *      If not satisfied → return [FireResult.WaitingForCompound].     *   3. Execute the action via [executeAction].     *   4. Mark the rule as fired (lastFiredAt + fireCount).     *     * @param ruleId       the rule to fire.     * @param sourceTrigger optional — for compound triggers, which child fired.     *                      `null` means the rule's own trigger fired.     * @return the [FireResult] describing what happened.     */    suspend fun fireRule(ruleId: String, sourceTrigger: AutomationTrigger? = null): FireResult {        val rule = rules[ruleId] ?: run {            Timber.tag(TAG).w("fireRule: rule %s not found", ruleId)            return FireResult.Skipped("Rule $ruleId not found")        }        if (!rule.isEnabled) {            Timber.tag(TAG).w("fireRule: rule '%s' is disabled — skipping", rule.name)            return FireResult.Skipped("Rule '${rule.name}' is disabled")        }        // Compound trigger evaluation.        val trigger = rule.trigger        if (trigger is AutomationTrigger.CompoundTrigger && sourceTrigger != null) {            if (!evaluateCompoundTrigger(rule, sourceTrigger)) {                Timber.tag(TAG).d("fireRule: compound trigger for '%s' not yet satisfied", rule.name)                return FireResult.WaitingForCompound(rule.id)            }        }        Timber.tag(TAG).i("Firing rule '%s' (id=%s)", rule.name, rule.id)        val actionResult = executeAction(rule.action, rule)        // Update fire statistics.        rules[ruleId] = rule.markFired()        return FireResult.Fired(rule.id, actionResult)    }    /**     * Manually fire a rule — used for testing + "fire now" UI button.     *     * Bypasses compound-trigger evaluation — always fires the action.     */    suspend fun manuallyFire(ruleId: String): FireResult {        val rule = rules[ruleId] ?: return FireResult.Skipped("Rule $ruleId not found")        Timber.tag(TAG).i("Manual fire: '%s' (id=%s)", rule.name, rule.id)        val actionResult = executeAction(rule.action, rule)        rules[ruleId] = rule.markFired()        return FireResult.Fired(rule.id, actionResult)    }    /**     * Execute a single [AutomationAction].     *     * Recursively handles [AutomationAction.ChainAction] — each sub-action     * is executed in sequence. One failure does NOT abort the chain.     */    private suspend fun executeAction(        action: AutomationAction,        rule: AutomationRule,    ): ActionResult {        return when (action) {            is AutomationAction.SystemAction -> executeSystemAction(action)            is AutomationAction.SkillAction -> executeSkillAction(action, rule)            is AutomationAction.SpeakAction -> executeSpeakAction(action)            is AutomationAction.NotifyAction -> executeNotifyAction(action, rule)            is AutomationAction.ChainAction -> {                val subResults = mutableListOf<ActionResult>()                for (sub in action.actions) {                    val subResult = executeAction(sub, rule)                    subResults += subResult                    if (subResult is ActionResult.Failed) {                        Timber.tag(TAG).w(                            "Chain step failed in rule '%s': %s — continuing",                            rule.name, subResult.reason,                        )                    }                }                val failed = subResults.count { it is ActionResult.Failed }                if (failed == 0) {                    ActionResult.Succeeded("Chain: ${subResults.size}/${subResults.size} steps")                } else {                    ActionResult.PartiallySucceeded(                        message = "Chain: ${subResults.size - failed}/${subResults.size} steps",                        failures = failed,                    )                }            }        }    }    /** Execute a [AutomationAction.SystemAction] via [SystemOperationExecutor]. */    private suspend fun executeSystemAction(action: AutomationAction.SystemAction): ActionResult {        val result = systemExecutor.execute(action.operation)        return when (result) {            is Result.Success -> ActionResult.Succeeded(                "System: ${action.operation::class.simpleName}",            )            is Result.Failure -> ActionResult.Failed(                "System: ${action.operation::class.simpleName} failed — ${result.error.message}",            )            is Result.Partial -> ActionResult.PartiallySucceeded(                message = "System: ${action.operation::class.simpleName} partial — ${result.warnings.joinToString()}",                failures = result.warnings.size,            )        }    }    /**     * Execute a [AutomationAction.SkillAction].     *     * Emits a BrainEvent so the Brain orchestrator can route the synthetic     * intent on its next cycle. Direct synchronous skill execution would     * require constructing a full BrainContext (with persona, ambient     * snapshot, budget, etc.) — that's out-of-scope for Module 8.     *     * TODO(v2): construct a minimal BrainContext + invoke SkillRouter.route()     *           directly. For now, the event is emitted and logged.     */    private suspend fun executeSkillAction(        action: AutomationAction.SkillAction,        rule: AutomationRule,    ): ActionResult {        val correlationId = CorrelationId.generate()        Timber.tag(TAG).i(            "SkillAction requested: skill='%s' params=%s rule='%s' correlationId=%s",            action.skillId, action.params, rule.name, correlationId,        )        // Emit an event so the Brain (or another listener) can pick it up.        // Brain's SkillInvoked event is for AFTER a skill runs — we need a        // pre-invocation event. For now, log + emit a generic SkillInvoked.        brainBus.tryEmit(            com.roshan.persona.brain.bus.BrainEvent.SkillInvoked(                skillId = action.skillId,                intentLabel = "automation:${rule.id}",                correlationId = correlationId,            ),        )        return ActionResult.Succeeded(            "Skill '${action.skillId}' requested (correlationId=$correlationId)",        )    }    /**     * Execute a [AutomationAction.SpeakAction] via Android TextToSpeech.     *     * Initializes TTS on first use (lazy). The TTS engine speaks [text]     * with `QUEUE_ADD` — multiple speaks are queued, not interrupted.     */    private fun executeSpeakAction(action: AutomationAction.SpeakAction): ActionResult {        val engine = getOrInitTts()        engine?.speak(action.text, TextToSpeech.QUEUE_ADD, null, "automation_${System.currentTimeMillis()}")        Timber.tag(TAG).i("TTS speak: '%s' (queued=%b)", action.text.take(80), engine != null)        return ActionResult.Succeeded(            if (engine != null) "Spoke: '${action.text.take(80)}'"            else "TTS unavailable — speak skipped",        )    }    /**     * Execute a [AutomationAction.NotifyAction] via NotificationManager.     *     * Creates the notification channel (API 26+) + posts a high-priority     * notification with a stable ID derived from the rule ID's hashCode.     */    private fun executeNotifyAction(        action: AutomationAction.NotifyAction,        rule: AutomationRule,    ): ActionResult {        ensureNotificationChannel()        val notificationId = NOTIFICATION_ID_BASE + (rule.id.hashCode() and 0xFFF)        val builder = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)            .setSmallIcon(android.R.drawable.ic_popup_reminder)            .setContentTitle(action.title)            .setContentText(action.message)            .setStyle(NotificationCompat.BigTextStyle().bigText(action.message))            .setPriority(NotificationCompat.PRIORITY_HIGH)            .setCategory(NotificationCompat.CATEGORY_REMINDER)            .setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION))            .setVibrate(longArrayOf(0, 300, 200, 300))            .setAutoCancel(true)        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager            ?: return ActionResult.Failed("NotificationManager unavailable on this device")        nm.notify(notificationId, builder.build())        Timber.tag(TAG).i("Notify: '%s' — '%s' (notifId=%d)", action.title, action.message, notificationId)        return ActionResult.Succeeded("Notified: ${action.title}")    }    // ═══════════════════════════════════════════════════════════════════════════    // Compound trigger evaluation    // ═══════════════════════════════════════════════════════════════════════════    /**     * Evaluate a compound trigger after a child fires.     *     * For `OR`: always returns `true` — any child firing causes the parent to fire.     * For `AND`: returns `true` only if ALL children have fired within the     *           recent window (default 5 minutes).     */    private fun evaluateCompoundTrigger(        rule: AutomationRule,        firedChild: AutomationTrigger,    ): Boolean {        val compound = rule.trigger as? AutomationTrigger.CompoundTrigger            ?: return false  // Not a compound trigger — can't evaluate        val now = System.currentTimeMillis()        val windowMs = 5 * 60 * 1000L  // 5 minutes        val history = compoundFireHistory.computeIfAbsent(rule.id) { mutableListOf() }        // Record this fire.        synchronized(history) {            history.add(now)            // Trim entries outside the window.            history.removeAll { it < now - windowMs }        }        // OR: always fire.        if (compound.operator == LogicalOperator.OR) return true        // AND: all children must have fired within the window.        // We approximate "all children fired" by counting distinct fires        // in the window — if the count >= number of children, assume all fired.        // (A more rigorous check would track which specific child fired; that's        // a v2 refinement — for now, this heuristic handles the common case        // of "all children fire within 5 minutes" correctly.)        val fireCount = synchronized(history) { history.size }        val allFired = fireCount >= compound.triggers.size        if (allFired) {            // Reset history so the next AND-cycle starts fresh.            synchronized(history) { history.clear() }        }        return allFired    }    // ═══════════════════════════════════════════════════════════════════════════    // Helpers    // ═══════════════════════════════════════════════════════════════════════════    /**     * Get the TTS engine, initializing lazily on first call.     *     * Returns `null` if TTS initialization fails (rare — usually means no     * TTS engine is installed on the device).     */    private fun getOrInitTts(): TextToSpeech? {        tts?.let { return it }        // Double-checked locking — TTS init is async, but the engine object        // itself is returned synchronously after construction.        synchronized(this) {            tts?.let { return it }            var initStatus = TextToSpeech.ERROR            val engine = TextToSpeech(context) { status -> initStatus = status }            // Wait briefly for init (TTS init is fast — usually <100ms).            // We don't block the calling thread for long; if init is slow,            // the first speak() may queue before TTS is ready, but the            // engine handles that internally.            // Note: kotlinx.coroutines.delay() is suspend — can't use here            // (this function is non-suspend). Use LockSupport.parkNanos for            // the brief wait instead — no InterruptedException baggage.            java.util.concurrent.locks.LockSupport.parkNanos(                java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(50)            )            if (initStatus == TextToSpeech.SUCCESS) {                engine.language = Locale.getDefault()                tts = engine                Timber.tag(TAG).i("TTS engine initialized (locale=${Locale.getDefault()})")                return engine            } else {                Timber.tag(TAG).w("TTS engine init failed (status=$initStatus)")                return null            }        }    }    /**     * Ensure the notification channel exists (API 26+ requirement).     */    private fun ensureNotificationChannel() {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return        if (nm.getNotificationChannel(NOTIFICATION_CHANNEL_ID) != null) return        val channel = NotificationChannel(            NOTIFICATION_CHANNEL_ID,            NOTIFICATION_CHANNEL_NAME,            NotificationManager.IMPORTANCE_HIGH,        ).apply {            description = "Notifications fired by NOUS Automation rules"            enableVibration(true)            setSound(                RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION),                AudioAttributes.Builder()                    .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)                    .setUsage(AudioAttributes.USAGE_NOTIFICATION)                    .build(),            )        }        nm.createNotificationChannel(channel)    }    /**     * Shutdown TTS engine — called by the Hilt-bound lifecycle when the     * app is being destroyed. Idempotent.     */    fun shutdown() {        tts?.stop()        tts?.shutdown()        tts = null        Timber.tag(TAG).i("TTS engine shut down")    }}// ─── Result types ────────────────────────────────────────────────────────────/** * Result of [AutomationEngine.fireRule]. */sealed interface FireResult {    /** Rule fired successfully + action was executed. */    data class Fired(val ruleId: String, val actionResult: ActionResult) : FireResult    /** Rule was not fired — disabled or not found. */    data class Skipped(val reason: String) : FireResult    /** Compound trigger's child fired but the parent condition isn't yet met. */    data class WaitingForCompound(val ruleId: String) : FireResult}/** * Result of executing a single [AutomationAction]. */sealed interface ActionResult {    /** Action completed successfully. */    data class Succeeded(val message: String) : ActionResult    /** Action failed. */    data class Failed(val reason: String) : ActionResult    /** Action partially succeeded (e.g., chain with some failed steps). */    data class PartiallySucceeded(val message: String, val failures: Int) : ActionResult}
